class_name MainController
extends Control

@onready var play_button: Button = $CenterContainer/VBoxContainer/PlayButton
@onready var title_label: Label = $CenterContainer/VBoxContainer/TitleLabel

var score_manager: ScoreManager


func _ready() -> void:
	score_manager = ScoreManager.new()
	if play_button:
		play_button.pressed.connect(_on_play_pressed)


func _on_play_pressed() -> void:
	if title_label:
		title_label.text = "Partita Avviata"

class_name CardView
extends PanelContainer

@onready var question_label: Label = $VBoxContainer/QuestionLabel
@onready var answer_0: Button = $VBoxContainer/Answer0
@onready var answer_1: Button = $VBoxContainer/Answer1

var current_data: QuestionData


func set_question(data: QuestionData) -> void:
	current_data = data
	if question_label and current_data:
		question_label.text = current_data.question_text
	if answer_0 and current_data and current_data.options.size() > 0:
		answer_0.text = current_data.options[0]
	if answer_1 and current_data and current_data.options.size() > 1:
		answer_1.text = current_data.options[1]

class_name QuestionData
extends Resource

@export var question_text: String = ""
@export var options: Array[String] = []
@export var correct_index: int = 0

